import sys; sys.path.insert(0,str(WORK))
import numpy as np
from lsbuild import gelu, layer_data
from evalh import Lb, lab1, f1
def LN(x,g,b): mu=x.mean(1,keepdims=True); v=x.var(1,keepdims=True); return (x-mu)/np.sqrt(v+1e-5)*g+b
ab,W1,b1,U,b2=layer_data(5,base); ae=np.load('a5e_1536.npy').astype(np.float64)
print(ab.shape, ae.shape)
pre='roberta.encoder.layer.5.'
g2=base(pre+'output.LayerNorm.weight').astype(np.float64); bb=base(pre+'output.LayerNorm.bias').astype(np.float64)
D=base('classifier.dense.weight').astype(np.float64); bd=base('classifier.dense.bias'); O=base('classifier.out_proj.weight'); bo=base('classifier.out_proj.bias')
head=lambda h: np.tanh(h@D.T+bd)@O.T+bo
Gb=gelu(ab@W1.T+b1); Ge=gelu(ae@W1.T+b1); xb=ab+Gb@U.T+b2; hb=LN(xb,g2,bb)
print('head(hb) vs Lb', np.abs(head(hb)-Lb).max())
# unpruned FFN on edited input:
he_full=LN(ae+Ge@U.T+b2,g2,bb); 
def r2(h): return 1-((h-hb)**2).sum()/((hb-hb.mean(0))**2).sum()
def agr(h): return (head(h).argmax(1)==Lb.argmax(1)).mean()
print('full FFN on edited input: R2 %.4f agree %.3f'%(r2(he_full),agr(he_full)))
folds=np.load('folds.npy')
def fit(Xs,Ts,ws,m,lam,keep=None):
    X=np.vstack(Xs);T=np.vstack(Ts);w=np.concatenate(ws)
    sw=np.sqrt(w)[:,None]; mu=(w[:,None]*X).sum(0)/w.sum(); tm=(w[:,None]*T).sum(0)/w.sum()
    Xc=(X-mu)*sw
    if keep is None:
        sc=(U**2).sum(0)*(Xc**2).sum(0); keep=np.sort(np.argsort(-sc)[:m])
    Xk=Xc[:,keep]; R=(T-tm)*sw-Xk@U[:,keep].T
    Dd=np.linalg.solve(Xk.T@Xk+lam*np.eye(len(keep)),Xk.T@R).T
    Un=U[:,keep]+Dd; b2n=tm-Un@mu[keep]
    return keep,Un,b2n
for m in [1536,1792]:
    for mode in ['base','mixed']:
        for lam in [10,30,100,300]:
            He=np.zeros_like(hb); Hb2=np.zeros_like(hb)
            for f in range(10):
                tr=folds!=f; te=folds==f
                if mode=='base': keep,Un,b2n=fit([Gb[tr]],[xb[tr]-ab[tr]],[np.ones(tr.sum())],m,lam)
                else: keep,Un,b2n=fit([Gb[tr],Ge[tr]],[xb[tr]-ab[tr],xb[tr]-ae[tr]],[np.ones(tr.sum())]*2,m,lam)
                He[te]=LN(ae[te]+Ge[te][:,keep]@Un.T+b2n,g2,bb)
                Hb2[te]=LN(ab[te]+Gb[te][:,keep]@Un.T+b2n,g2,bb)
            print(m,mode,lam,'CV edited-input R2 %.4f agree %.3f | base-input R2 %.4f agree %.3f'%(r2(He),agr(He),r2(Hb2),agr(Hb2)))
